/**
 * Attributes the renderer bundle's bytes to the packages that produced them.
 *
 * `bench-size.mjs` reports that `dist/` is 13.5 MB. That is the number to act
 * on only once you know *what* is in it, which is what
 * [BUNDLE_SIZE_PLAN.md](../../docs/BUNDLE_SIZE_PLAN.md) needs and nothing
 * currently provides.
 *
 * Method: build once with sourcemaps into a scratch directory, then decode each
 * chunk's mappings and charge every generated segment to the source file it came
 * from, grouping by npm package. This is what source-map-explorer does, and
 * doing it here avoids adding a build-time dependency to the real config - the
 * production build stays sourcemap-free.
 *
 * The alternative - summing `sourcesContent` lengths - was rejected: it measures
 * *source* bytes, so a comment-heavy package looks enormous even when it minifies
 * to nothing. Mapping segments measure shipped bytes.
 *
 *   node scripts/bench/bench-bundle.mjs --out results.json
 *   node scripts/bench/bench-bundle.mjs --reuse   # skip the build, use dist/
 */

import { execFileSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import zlib from "node:zlib";

import { fmtBytes } from "./lib/stats.mjs";

const here = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(here, "..", "..");

const argv = process.argv.slice(2);
const flag = (name, fallback = null) => {
  const i = argv.indexOf(name);
  return i !== -1 && argv[i + 1] ? argv[i + 1] : fallback;
};
const OUT = flag("--out", null);
const REUSE = argv.includes("--reuse");
const TOP = Number(flag("--top", "25"));

// --------------------------------------------------------- VLQ decoding ---

const B64 =
  "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const CHAR_INDEX = new Map([...B64].map((c, i) => [c, i]));

/** Decodes one base64-VLQ group into its integer fields. */
function decodeVlq(segment) {
  const values = [];
  let shift = 0;
  let value = 0;
  for (const char of segment) {
    const digit = CHAR_INDEX.get(char);
    if (digit === undefined) return values;
    const continues = digit & 32;
    value += (digit & 31) << shift;
    if (continues) {
      shift += 5;
    } else {
      const negative = value & 1;
      value >>= 1;
      values.push(negative ? -value : value);
      value = 0;
      shift = 0;
    }
  }
  return values;
}

/**
 * Charges generated bytes to source files.
 *
 * Each mapping segment marks where a source's output begins on a generated
 * line; the span to the next segment (or end of line) is that source's share.
 * Bytes before the first segment of a line belong to no source - bundler
 * scaffolding - and are counted as unattributed rather than silently dropped.
 */
function attribute(code, map) {
  const perSource = new Map();
  let unattributed = 0;

  const generatedLines = code.split("\n");
  let sourceIndex = 0;

  const lines = map.mappings.split(";");
  for (let lineNo = 0; lineNo < lines.length; lineNo++) {
    const lineLength = (generatedLines[lineNo] ?? "").length;
    if (!lines[lineNo]) {
      unattributed += lineLength;
      continue;
    }

    const segments = lines[lineNo].split(",");
    let generatedColumn = 0;
    const marks = [];

    for (const segment of segments) {
      const fields = decodeVlq(segment);
      if (fields.length === 0) continue;
      generatedColumn += fields[0];
      if (fields.length >= 4) sourceIndex += fields[1];
      marks.push({ column: generatedColumn, source: fields.length >= 4 ? sourceIndex : null });
    }

    if (marks.length === 0) {
      unattributed += lineLength;
      continue;
    }

    unattributed += Math.max(0, marks[0].column);
    for (let i = 0; i < marks.length; i++) {
      const end = i + 1 < marks.length ? marks[i + 1].column : lineLength;
      const span = Math.max(0, end - marks[i].column);
      if (marks[i].source === null) {
        unattributed += span;
        continue;
      }
      const name = map.sources[marks[i].source] ?? "(unknown)";
      perSource.set(name, (perSource.get(name) ?? 0) + span);
    }
  }

  return { perSource, unattributed };
}

/** Collapses a source path to the package (or app area) that owns it. */
function ownerOf(sourcePath) {
  const normalised = sourcePath.replace(/\\/g, "/");
  const nm = normalised.lastIndexOf("node_modules/");
  if (nm !== -1) {
    const rest = normalised.slice(nm + "node_modules/".length).split("/");
    return rest[0].startsWith("@") ? `${rest[0]}/${rest[1]}` : rest[0];
  }
  if (normalised.includes("/src/")) {
    const parts = normalised.split("/src/")[1].split("/");
    return parts.length > 1 ? `src/${parts[0]}` : "src";
  }
  return "(other)";
}

// ---------------------------------------------------------------- build ---

let distDir = path.join(repoRoot, "dist");
let scratch = null;

if (!REUSE) {
  scratch = fs.mkdtempSync(path.join(os.tmpdir(), "mindsage-bench-bundle-"));
  distDir = path.join(scratch, "dist");
  console.log("  building with sourcemaps (this takes a minute)...");
  try {
    // vite's JS entry is invoked directly rather than through npx: recent Node
    // refuses to spawnSync a .cmd shim without `shell: true` (EINVAL), and
    // enabling a shell just to launch a build invites quoting problems with
    // paths that contain spaces.
    execFileSync(
      process.execPath,
      [
        path.join(repoRoot, "node_modules", "vite", "bin", "vite.js"),
        "build",
        "--sourcemap",
        "--outDir",
        distDir,
        "--emptyOutDir",
      ],
      { cwd: repoRoot, stdio: "ignore" }
    );
  } catch (err) {
    console.error(`vite build failed: ${err.message}`);
    process.exit(1);
  }
}

const assetsDir = path.join(distDir, "assets");
if (!fs.existsSync(assetsDir)) {
  console.error(`No assets directory at ${assetsDir}. Run npm run build first, or drop --reuse.`);
  process.exit(1);
}

// -------------------------------------------------------------- analyse ---

const owners = new Map();
const chunks = [];
let unattributedTotal = 0;
let mapsFound = 0;

for (const file of fs.readdirSync(assetsDir)) {
  if (!file.endsWith(".js")) continue;
  const full = path.join(assetsDir, file);
  const code = fs.readFileSync(full, "utf8");
  const bytes = Buffer.byteLength(code);

  chunks.push({
    file,
    bytes,
    gzipBytes: zlib.gzipSync(code).length,
  });

  const mapPath = `${full}.map`;
  if (!fs.existsSync(mapPath)) continue;
  mapsFound++;

  const map = JSON.parse(fs.readFileSync(mapPath, "utf8"));
  const { perSource, unattributed } = attribute(code, map);
  unattributedTotal += unattributed;

  for (const [source, size] of perSource) {
    const owner = ownerOf(source);
    owners.set(owner, (owners.get(owner) ?? 0) + size);
  }
}

// CSS is not sourcemapped through this path but still ships.
let cssBytes = 0;
for (const file of fs.readdirSync(assetsDir)) {
  if (file.endsWith(".css")) cssBytes += fs.statSync(path.join(assetsDir, file)).size;
}

chunks.sort((a, b) => b.bytes - a.bytes);
const ranked = [...owners.entries()].sort((a, b) => b[1] - a[1]);
const totalJs = chunks.reduce((sum, c) => sum + c.bytes, 0);
const totalGzip = chunks.reduce((sum, c) => sum + c.gzipBytes, 0);

const report = {
  sourcemapsAnalysed: mapsFound,
  totals: {
    javascriptBytes: totalJs,
    javascriptGzipBytes: totalGzip,
    cssBytes,
    unattributedBytes: unattributedTotal,
  },
  byOwner: Object.fromEntries(ranked.slice(0, TOP)),
  largestChunks: chunks.slice(0, 15),
  note:
    mapsFound === 0
      ? "No sourcemaps found - only chunk sizes are reported. Run without --reuse for per-package attribution."
      : "Bytes attributed by decoding sourcemap mappings; unattributed bytes are bundler scaffolding.",
};

if (OUT) {
  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  fs.writeFileSync(OUT, JSON.stringify(report, null, 2));
}

console.log(
  `  ${"total JavaScript".padEnd(30)} ${fmtBytes(totalJs)}  (${fmtBytes(totalGzip)} gzipped)`
);
console.log(`  ${"total CSS".padEnd(30)} ${fmtBytes(cssBytes)}`);
console.log(`  ${"unattributed (scaffolding)".padEnd(30)} ${fmtBytes(unattributedTotal)}`);
console.log("  --- largest owners ---");
for (const [owner, size] of ranked.slice(0, 15)) {
  console.log(`  ${owner.padEnd(30)} ${fmtBytes(size).padStart(10)}`);
}

if (scratch) fs.rmSync(scratch, { recursive: true, force: true });
